# Own-wording items of Griffon's Saddlebag, Book 1 (2024), names A to Dragon Turtle Shield. Row shape as tghp_item.py and tsgeh_item.py.
# Weapons based on a standard weapon use base and fx (bonus to attack and damage). Armor and shields use base and fx ac.
ITEMS = []; SP = {}; WPN = {}; GEAR = []
def add(name, typ, rar, att, text, **o):
    ITEMS.append((name, typ, rar, att, text, o))
MASTERY = {}; WDESC = {}

add("Abjurer's Gilder", "Wondrous Item", "Uncommon", 1, "A golden badge for Wizards who excel at Abjuration. Shield is always prepared for you if it is in your spellbook, and it does not count against your prepared spells. You can also cast Shield as a special Reaction when hit by an attack roll or targeted by Magic Missile. It works once per turn cycle (not again until the start of your next turn) and does not use up your normal Reaction.", by="Wizard")
add("Aegis of Radiance", "Armor", "Rare", 1, "A Shield with an extra +1 bonus to AC that serves as a Holy Symbol and shows your deity's emblem. Bonus Action with a command word: it shatters into shards of light that protect you like a held Shield and leave your hands free. The shards last 1 minute, shed Bright Light in 20 ft and Dim Light 20 ft more, and give Undead Disadvantage on attacks against you. Usable once per dawn.", fx={"ac": 1}, base=["Shield"], by="Cleric", ch=[1, "1", "dawn"])
add("Amulet of Equilibrium", "Wondrous Item", "Uncommon", 1, "A three-crystal pendant that works as a Spellcasting Focus. It has 4 charges and regains 2 at dawn. When you deal Cold, Fire or Lightning damage to only one creature, spend any number of charges to reroll that many damage dice (you must use the new rolls). Taking Cold, Fire or Lightning damage from an enemy restores 1 charge.", ch=[4, "2", "dawn"])
add("Arcane Mirror", "Armor", "Very Rare", 1, "A Shield that holds 10 charges and regains 1d6 + 4 at dawn. Reaction when hit by an attack: cast Shield from it (once per Short or Long Rest). Reaction after you pass a save against a single-target spell or a spell attack misses you: learn its level, then spend charges equal to that level (not 7 or higher) to reflect it. The caster makes a DC 16 Dexterity save and takes 1d8 Radiant per charge spent (half on a success). If a reflected spell would have dealt half damage on a success, you take none.", base=["Shield"], ch=[10, "1d6 + 4", "dawn"])
SP["Arcane Mirror"] = {"sp": [["Shield", 0]]}
add("Arcanist's Bowstaff", "Staff", "Very Rare", 1, "A Quarterstaff that can curve into a Longbow when you attack at range. You are proficient with that bow and it lacks Heavy. It fires arcane arrows it makes itself and returns to a staff afterward. You gain +2 to attack and damage rolls and may use Intelligence for them. It has 8 charges and regains 1d6 + 2 at dawn. After an attack roll as part of the Attack action, spend 1 charge to cast Magic Missile as a Bonus Action.", fx={"atk": 2, "dmg": 2}, base=["Quarterstaff"], by="Creature with Intelligence 17 or higher", ch=[8, "1d6 + 2", "dawn"])
SP["Arcanist's Bowstaff"] = {"sp": [["Magic Missile", 1]]}
add("Architect's Disdain", "Weapon", "Very Rare", 1, "An adamantine War Pick made to break walls. You gain +2 to attack and damage rolls. Every hit on an object or structure is a Critical Hit. A hit on a magically created object or structure (such as a Wall of Ice) can dispel it as Dispel Magic at level 6, but this fails if it was made with a level 7 or higher slot. Once it dispels something, it cannot do so again until the next dawn.", fx={"atk": 2, "dmg": 2}, base=["War Pick"], ch=[1, "1", "dawn"])
_ab = "A wondrous bangle that you can pull off and hold as a Magic action, when it unfolds into an astronomical sphere. It has 10 charges, usable only in sphere form, and regains 2d4 + 2 at dawn. Spending its last charge folds it back into a bracelet, and a Magic action folds it early. While holding the sphere you can spend charges to cast its listed spells with your spellcasting ability and spell save DC. Material components costing 100 gp or more are still needed."
add("Astral Bracelet", "Wondrous Item", "Very Rare", 0, "The base form of a family of six bracelets (Energy, Heavens, Hells, Knowledge, Omniscience, Planebending). " + _ab, ch=[10, "2d4 + 2", "dawn"])
add("Astral Bracelet of Energy", "Wondrous Item", "Very Rare", 1, _ab + " Spells: Tenser's Floating Disk (1 charge), Dispel Magic (3), Hypnotic Pattern (3), Protection from Energy (3), Hallucinatory Terrain (4), Otiluke's Resilient Sphere (4), Globe of Invulnerability (6).", by="Sorcerer or Wizard", ch=[10, "2d4 + 2", "dawn"])
SP["Astral Bracelet of Energy"] = {"sp": [["Floating Disk", 1], ["Dispel Magic", 3], ["Hypnotic Pattern", 3], ["Protection from Energy", 3], ["Hallucinatory Terrain", 4], ["Resilient Sphere", 4], ["Globe of Invulnerability", 6]]}
add("Astral Bracelet of Heavens", "Wondrous Item", "Very Rare", 1, _ab + " Spells: Detect Evil and Good (1 charge), Protection from Evil and Good (1), Warding Bond (2), Magic Circle (3), Spirit Guardians (3), Divination (4), Dispel Evil and Good (5).", by="Cleric or Paladin", ch=[10, "2d4 + 2", "dawn"])
SP["Astral Bracelet of Heavens"] = {"sp": [["Detect Evil and Good", 1], ["Protection from Evil and Good", 1], ["Warding Bond", 2], ["Magic Circle", 3], ["Spirit Guardians", 3], ["Divination", 4], ["Dispel Evil and Good", 5]]}
add("Astral Bracelet of Hells", "Wondrous Item", "Very Rare", 1, _ab + " Spells: Detect Evil and Good (1 charge), Hellish Rebuke (1), Protection from Evil and Good (1), Flaming Sphere (2), Magic Circle (3), Fire Shield (4), Dispel Evil and Good (5).", by="Cleric, Warlock or Wizard", ch=[10, "2d4 + 2", "dawn"])
SP["Astral Bracelet of Hells"] = {"sp": [["Detect Evil and Good", 1], ["Hellish Rebuke", 1], ["Protection from Evil and Good", 1], ["Flaming Sphere", 2], ["Magic Circle", 3], ["Fire Shield", 4], ["Dispel Evil and Good", 5]]}
add("Astral Bracelet of Knowledge", "Wondrous Item", "Very Rare", 1, _ab + " Spells: Comprehend Languages (1 charge), Detect Magic (1), Identify (1), Locate Object (2), Dispel Magic (3), Sending (3), Locate Creature (4), Legend Lore (5).", by="Bard, Cleric, Druid, Ranger or Wizard", ch=[10, "2d4 + 2", "dawn"])
SP["Astral Bracelet of Knowledge"] = {"sp": [["Comprehend Languages", 1], ["Detect Magic", 1], ["Identify", 1], ["Locate Object", 2], ["Dispel Magic", 3], ["Sending", 3], ["Locate Creature", 4], ["Legend Lore", 5]]}
add("Astral Bracelet of Omniscience", "Wondrous Item", "Very Rare", 1, _ab + " Spells: Detect Magic (1 charge), Detect Thoughts (2), See Invisibility (2), Sending (3), Arcane Eye (4), Scrying (5), Telepathic Bond (5).", by="Wizard", ch=[10, "2d4 + 2", "dawn"])
SP["Astral Bracelet of Omniscience"] = {"sp": [["Detect Magic", 1], ["Detect Thoughts", 2], ["See Invisibility", 2], ["Sending", 3], ["Arcane Eye", 4], ["Scrying", 5], ["Telepathic Bond", 5]]}
add("Astral Bracelet of Planebending", "Wondrous Item", "Very Rare", 1, _ab + " Spells: Find Familiar (1 charge), Misty Step (2), Rope Trick (2), Sending (3), Banishment (4), Dimension Door (4), Plane Shift (7).", by="Sorcerer, Warlock or Wizard", ch=[10, "2d4 + 2", "dawn"])
SP["Astral Bracelet of Planebending"] = {"sp": [["Find Familiar", 1], ["Misty Step", 2], ["Rope Trick", 2], ["Sending", 3], ["Banishment", 4], ["Dimension Door", 4], ["Plane Shift", 7]]}
add("Astral Sea Piercer", "Weapon", "Legendary", 1, "A golden War Pick forged in the Astral Plane. You gain +3 to attack and damage rolls and a hit deals an extra 1d4 Force. In the Astral Plane you know the way to the nearest portal. It has 4 charges and regains 1d3 + 1 at dawn. **Portal.** Bonus Action, 1 charge: plant it in a flat surface to make a rift lasting 1 minute. A second rift within 300 ft opens a portal between them until the end of your next turn (closable early). Medium or smaller creatures and objects pass freely. **Rift Strike.** When you hit a Small or larger creature, spend 1 charge for an extra 1d8 Force and a rift on its body. When a portal opens to it, the creature makes a DC 17 Charisma save or is shunted through (Large and larger pass automatically).", fx={"atk": 3, "dmg": 3}, base=["War Pick"], ch=[4, "1d3 + 1", "dawn"])
add("Aurum and Argentum", "Weapon", "Rare", 0, "A gold and silver pair of Daggers that become magical when used together. You gain +1 to attack and damage rolls while holding one in each hand. The extra attack from the Light property can add your ability modifier to its damage. If both hit the same target in a round, the second attack deals an extra 1d4 Piercing and the target cannot make Opportunity Attacks until the end of your turn.", fx={"atk": 1, "dmg": 1}, base=["Dagger"])
add("Avian Circlet", "Wondrous Item", "Rare", 0, "A silver tiara that gives power over flying creatures. You can cast Animal Messenger or Speak with Animals from it, but only on targets with a Fly Speed. Magic action: touch a willing Beast with a Fly Speed to see through its eyes (and use its special visual senses) for 1 minute. You can end it early. Usable once per dawn.", ch=[1, "1", "dawn"])
SP["Avian Circlet"] = {"sp": [["Animal Messenger", 0], ["Speak with Animals", 0]]}
add("Axe Beak Tomahawk", "Weapon", "Uncommon", 0, "A Handaxe made from a slain axe beak. The first time each turn you hit a creature with a Fly Speed, it makes a DC 13 Strength save. Each failure reduces its Fly Speed by 15 ft for 1 minute.", base=["Handaxe"])
add("Bag of Sundrops", "Wondrous Item", "Uncommon", 0, "A bag holding 1d6 + 4 glowing golden orbs. Magic action: throw one at a point you can see within 30 ft. It bursts into a pillar of sunlight (5-ft radius, 40 ft high Cylinder) of Bright Light that lasts until the start of your next turn. Dispel Magic on it ends it early.")
add("Band of Mirrored Essence", "Ring", "Rare", 1, "A mirror-polished platinum ring. When you reduce a Small or larger enemy to 0 Hit Points, use a Reaction to capture a bit of its essence (the ring holds one at a time and cannot capture again for 1d8 hours). Magic action: release it to take the creature's appearance or one feature. **Appearance.** An illusion of a creature up to one size larger or smaller, lasting 8 hours (DC 16 Intelligence (Investigation) sees through it). **Feature.** Gain one skill or save proficiency, Damage Resistance, Condition Immunity, special sense, language, or water breathing it had, for 8 hours.")
add("Bands of the Found and Lost", "Wondrous Item", "Common", 0, "A pair of leather bracelets with compasses. While two creatures each wear one, each compass points at the other (direction only, not height or depth). They spin wildly if the bands are on different planes.")
add("Bard-in-a-Box", "Wondrous Item", "Common", 0, "A music box. Bonus Action while holding it: command it to play a song it knows, in tinny form without lyrics, at any volume. It remembers up to five songs from sheet music (labeled with song title, page number and instrument) fed into its slot. The sheet is consumed, and a sixth song makes it forget the oldest.")
add("Barge Helm", "Wondrous Item", "Uncommon", 0, "A flat, rugged helmet. If you move at least 20 ft in a straight line toward a target right before you shove it, the target takes 1d6 Bludgeoning damage.")
add("Barricade Shield", "Armor", "Uncommon", 0, "A sturdy iron Shield. Magic action: plant it to grow up to 15 ft in height and width, fitting enclosed spaces like tunnels. While holding it expanded your Speed is 0 and you have Disadvantage on Dexterity checks and saves. It stays the same weight and becomes a nonmagical object with AC 14 and HP 40. It lasts 1 minute and reverts early if destroyed or moved (or by your Bonus Action). Usable once per dawn.", base=["Shield"], ch=[1, "1", "dawn"])
add("Basco's Handy Bangle", "Wondrous Item", "Rare", 0, "A platinum bangle with ten tool runes: Alchemist's Supplies, Calligrapher's Supplies, Carpenter's Tools, Cook's Utensils, Leatherworker's Tools, Smith's Tools, Tinker's Tools, Musical Instruments (drum, flute, lute, lyre), Navigator's Tools and Thieves' Tools. Magic action: touch a rune and say the command words to gain proficiency with that tool for 24 hours, or Expertise if already proficient. A used rune cannot be used again for 1d4 days.")
add("Basilisk Dagger", "Weapon", "Rare", 0, "A Dagger from a slain basilisk. It deals an extra 1d4 Poison on a hit. When you roll a 20 on an attack roll with it against a Large or smaller creature, the target makes a DC 15 Constitution save or is Restrained until the end of your next turn.", base=["Dagger"], xd=["Poison: +1d4"])
add("Bath Potion", "Potion", "Common", 0, "A frothy, lavender-scented potion. Drinking it rinses away dirt and grime and leaves your breath, hair and nails clean for 24 hours, polished or scented of daisies and honey. Bubbles escape your mouth while it lasts.")
add("Baton of Many Sizes", "Rod", "Uncommon", 0, "A segmented 1-ft rod. Magic action with a command word: extend it in either direction up to 50 ft, stopping when it touches a creature or surface. Beyond 10 ft it is unwieldy: at the start of each of your turns make a Strength (Athletics) check against DC 8 + 1 per 5 ft past 10, or lose your grip. Dropping it or attacking with it retracts it. The command word as a Magic action retracts it too.")
add("Battle Tax", "Weapon", "Uncommon", 1, "A golden Battleaxe favored by merchants. You gain +1 to attack and damage rolls. When you roll a 20 on an attack roll against a Small or larger enemy, you magically earn Gold Pieces equal to the attack's damage, put in your pack or purse (or sprayed from the target if you have no room). It then cannot create coins for 12 hours.", fx={"atk": 1, "dmg": 1}, base=["Battleaxe"])
add("Battlebrew Maul", "Weapon", "Rare", 0, "A Maul whose head is an alchemical keg of battlebrew liquor (holds 4 gallons, makes 1 gallon at dawn and 1 more when you roll Initiative). Utilize action to detach the handle or to pour or stopper it. You gain +1 to attack and damage rolls. On a 20 to hit, the target takes an extra 2d6 Acid, and the next Fire damage it takes within 1 minute deals an extra 2d6 Fire.", fx={"atk": 1, "dmg": 1}, base=["Maul"])
add("Battlechef Buckler", "Armor", "Uncommon", 0, "A small Shield that was a famed chef's pot lid. While wielding it you have Advantage on saves against Fire damage. Placed face down over a pot with up to 2 gallons of water-based liquid, it brings the liquid to a boil after 10 minutes.", base=["Shield"])
add("Battlechef's Splendid Saucepan", "Wondrous Item", "Very Rare", 0, "A saucepan that turns up to 1 pound of nonmagical organic material boiled for 10 minutes or more into a stew that feeds four for a day. It works as a Mace with +1 to attack and damage rolls and deals an extra 1d4 Thunder to a target in metal armor or made of metal or stone. If you wear no Heavy armor, Utilize action to wear it as a helmet for +1 AC, or to remove it.")
add("Belt of the Raid Leader", "Wondrous Item", "Rare", 1, "A rivet-studded belt with a skull buckle. Magic action: a war cry that gives you and up to five allies within 60 ft who can hear you Advantage on attack rolls until the start of your next turn. You also make one weapon or Unarmed Strike attack as a Bonus Action. Usable once per dawn.", by="Orc", ch=[1, "1", "dawn"])
add("Bird of a Feather (Common)", "Wondrous Item", "Common", 0, "A stuffed roc toy filled with enchanted down. Magic action: gain a Fly Speed of 20 ft for 1 minute or until your Concentration ends. It carries up to 200 lb. Taking damage while flying ends the effect and you fall. When the effect ends, the toy becomes nonmagical.")
add("Bird of a Feather (Uncommon)", "Wondrous Item", "Uncommon", 0, "A stuffed roc toy filled with enchanted down. Magic action: gain a Fly Speed of 20 ft for 1 minute or until your Concentration ends. It carries up to 200 lb. Taking damage while flying ends the effect and you fall. This version stays magical but cannot be used again for 1d4 hours, and it chirps when ready.", ch=[1, "1", "dawn"])
add("Blizzard Sphere", "Wondrous Item", "Rare", 0, "A glass sphere holding a raging blizzard. Magic action: throw it at a creature or object within 30 ft to shatter it into a 20-ft-radius Emanation of ice and snow. A creature that first enters it on a turn or starts its turn there makes a DC 15 Constitution save, taking 4d8 Cold and having its Speed halved until the start of its next turn on a failure (half damage only on a success). The ground becomes Difficult Terrain and the area is Heavily Obscured. It lasts 1d4 rounds or until Dispel Magic (as a level 5 spell).")
add("Blood Pact Pendants", "Wondrous Item", "Very Rare", 0, "A pair of iron pendants. You and a close ally spend a 1-minute ritual to agree on Hit Points to sacrifice, lowering both of your Hit Point maximums by that amount (minimum 1). While both wear a pendant on the same plane, when one dies it revives at once with 2d10 Hit Points plus twice the Hit Points sacrificed. The other then drops to 0 Hit Points and is Unconscious, and both maximums return to normal. This ignores effects that stop a creature from reaching 0. After this the pendants crack and lose their magic.")
add("Bloodmage Dagger", "Weapon", "Very Rare", 1, "An obsidian Dagger usable as a Spellcasting Focus. You gain +1 to attack and damage rolls. It has 5 charges and regains 1d3 + 2 at dusk. **Blood Strike.** Magic action, 1 charge: a melee spell attack against a living creature within 5 ft deals 3d6 plus your spellcasting modifier Necrotic and heals you the same (no healing from Construct, Plant or Undead). **Blood Boost.** When you cast a level 1 to 3 spell on yourself or one creature, spend charges to raise the slot level by 1 each (max 5), and spend and roll that many Hit Point Dice, taking the total as Necrotic damage that ignores Resistance and Immunity. If it drops you to 0 Hit Points, the spell fails and you are Unconscious.", fx={"atk": 1, "dmg": 1}, base=["Dagger"], by="Spellcaster", ch=[5, "1d3 + 2", "dusk"])
add("Bloodscryer Oculus", "Wondrous Item", "Legendary", 1, "Red goggles with magnifying lenses. You ignore visual obscurity such as fog or smoke, and see normally in Dim Light and Darkness (magical or not) out to 60 ft, or 60 ft farther if you already have Darkvision. You have Advantage on sight-based Wisdom (Perception) checks. You can cast Hunter's Mark (level 3 version), Locate Creature or Scrying (no Concentration for it) from them, but only on creatures whose blood you can see. Each spell can be used once per dawn.", fx={"dark": 60}, by="Ranger")
SP["Bloodscryer Oculus"] = {"sp": [["Hunter's Mark", 1, 3], ["Locate Creature", 1], ["Scrying", 1]]}
add("Bolt", "Weapon", "Very Rare", 1, "A metal Heavy Crossbow that makes its own lightning ammunition when you draw the string. You gain +1 to attack and damage rolls, and it deals 1d12 Lightning instead of 1d10 Piercing. You have Advantage on ranged attacks with it against a metal target or a creature in metal armor. It also draws bolts: if another creature within 10 ft takes Lightning damage while you hold it, you take 1d6 Lightning per 10 damage that creature took.", fx={"atk": 1, "dmg": 1})
WPN["Bolt"] = {"d": "1d12", "t": "Lightning", "cat": "M", "k": "R", "p": "Heavy, Loading, Two-Handed", "m": "Push", "w": 18, "r": "100/400", "xw": 1}
add("Boots of Dendallen", "Wondrous Item", "Very Rare", 1, "Cursed fleshy boots. You gain a Fly Speed equal to your Speed and can hover up to 20 ft off the ground, and Dash moves you an extra 10 ft. They have 4 charges and regain 1d3 + 1 at dusk. Bonus Action, 1 charge: cast Expeditious Retreat or Misty Step (in dark mist). **Curse.** On first wearing, make a DC 16 Wisdom save. On a failure you take 4d8 Necrotic and cannot remove them without Remove Curse or similar magic. You then have Disadvantage on Dexterity (Acrobatics) checks and Dexterity saves and standing up costs 10 ft extra. Removing the boots deals another 4d8 Necrotic.", fx={"fly": "walk"}, ch=[4, "1d3 + 1", "dusk"])
SP["Boots of Dendallen"] = {"sp": [["Expeditious Retreat", 1], ["Misty Step", 1]]}
add("Boots of the Cloud Jumper", "Wondrous Item", "Uncommon", 1, "You can jump in midair as if from solid ground, treating it as a standing jump and never farther than your remaining movement. You can do this once before touching a solid surface again. A midair jump while falling lets you subtract up to 20 ft when calculating fall damage.")
add("Borboss' Joyous Wand of Color", "Wand", "Common", 0, "A prismatic crystal wand. You can draw strokes of color in midair or on any surface it touches. The drawing is illusory, visibly magical, sheds Dim Light in 5 ft and fades after 1 hour. Drawing on something worn or carried by an unwilling creature requires it to fail a DC 10 Dexterity save.")
add("Boreal Pendant", "Wondrous Item", "Rare", 1, "A floating snowflake that gives you Resistance to Cold damage and an aura of cheer. It has 8 charges and regains 1d6 + 2 at dawn. Spend charges to cast (save DC 15) Charm Person (1 charge), Color Spray (1), Hypnotic Pattern (3) or Ice Storm (4). If you spend the last charge, roll a d20. On a 1 the pendant melts, then reforms after 1 year.", fx={"res": ["Cold"]}, ch=[8, "1d6 + 2", "dawn"])
SP["Boreal Pendant"] = {"sp": [["Charm Person", 1], ["Color Spray", 1], ["Hypnotic Pattern", 3], ["Ice Storm", 4]], "dc": 15}
add("Bottled Abyss", "Potion", "Very Rare", 0, "A vial of fuming black poison. A creature that drinks it takes 4d6 Psychic and makes a DC 18 Constitution save. On a failure it is Blinded and cannot benefit from a Long Rest, and its sleep is full of nightmares. It repeats the save every 24 hours. The poison ends on a success or with Greater Restoration, Heal or Wish.")
add("Bounty Hunter Enforcer", "Weapon", "Uncommon", 0, "A Spear with a hollow head holding a spring-loaded Net. Its attacks deal Bludgeoning instead of Piercing. After a melee hit, Bonus Action: deploy the Net so a Large or smaller target is Restrained. Retracting and resetting it is a Utilize action. While it is deployed your Spear attacks have Disadvantage, and while something is Restrained by it you cannot make weapon attacks with the Spear. Bonus Action: prime it to deploy on the next hit, even thrown. A new Net takes 1 minute to attach.", base=["Spear"])
add("Bow of Mind Thievery", "Weapon", "Rare", 1, "A magic Shortbow whose Arrows deal an extra 1d4 Psychic. When an Arrow hits a Humanoid, it makes a DC 15 Wisdom save or is affected by Dominate Person for up to 1 minute with no Concentration needed. You can use a Bonus Action to see and hear through the target until the start of your next turn. Usable once per dawn.", base=["Shortbow"], xd=["Psychic: +1d4"], ch=[1, "1", "dawn"])
add("Braided Quarterstaff", "Weapon", "Uncommon", 0, "A Quarterstaff of braided rope. Bonus Action with a command word: it loosens into 50 ft of Rope, and again to tighten back. A Restrained creature held in the Rope can escape (or be freed by a creature within 5 ft) with an action and a DC 15 Strength (Athletics) check. An object up to 6 inches across tied to the end does not stop it re-forming. It can be broken only by magic, and if broken it becomes nonmagical and cannot be a staff again.", base=["Quarterstaff"])
add("Brambleheart Quiver", "Wondrous Item", "Very Rare", 1, "A wooden Quiver that holds your Arrows and has 4 thorned magic Arrows growing on it, regrowing 1d3 + 1 picked ones at dawn. While you are attuned, you gain +2 to attack and damage rolls with them. They lose their magic 1 minute after being picked. When one hits, use a Bonus Action with a command word for 2d4 extra Piercing and Spike Growth centered within 5 ft of the target, with no Concentration, lasting until the start of your next turn.", by="Druid or Ranger")
add("Breastplate of the Morning Light", "Armor", "Rare", 1, "A Breastplate that grants +1 AC. Magic action: a blinding flash of radiant light. Other creatures within 30 ft make a DC 15 Constitution save or are Blinded until the end of their next turn. Undead have Disadvantage on the save and take 2d8 Radiant on a failure (half on a success). Usable once per dawn.", fx={"ac": 1}, base=["Breastplate"], by="Cleric or Paladin", ch=[1, "1", "dawn"])
add("Brooch of Many Sizes", "Wondrous Item", "Rare", 0, "A dial brooch that lets you cast Enlarge/Reduce on yourself once per dawn. While it is active, Bonus Action: overload it to change size by one more category (not above Huge or below Tiny), with damage and weight changing as for a second casting. When you return to normal size after overloading, you are Incapacitated with Speed 0 until the end of your next turn, and its properties cannot be used again for 7 days.", ch=[1, "1", "dawn"])
SP["Brooch of Many Sizes"] = {"sp": [["Enlarge/Reduce", 1]]}
add("Bug Smashers", "Wondrous Item", "Uncommon", 0, "Gloves made from a giant centipede's barbed exoskeleton. Your Unarmed Strikes with them deal Bludgeoning or Piercing (your choice). On a 20 to hit with one, the target takes 2d6 Poison and makes a DC 13 Constitution save or is Poisoned until the start of your next turn.")
add("Cactus Mace", "Weapon", "Uncommon", 0, "A Mace with an enchanted cactus head that regrows its needles. The first target you hit with it each turn takes an extra 1d4 Piercing.", base=["Mace"], xd=["First hit each turn: +1d4 Piercing"])
add("Candle of Anti-Light", "Wondrous Item", "Uncommon", 0, "A dark candle that sheds magical Darkness in a 10-ft radius. It burns for up to 1 hour in total, and you can snuff or relight it as a Bonus Action. Covering it with something opaque blocks the Darkness. Darkvision cannot see through it and nonmagical light cannot light it up.")
add("Catnip Amulet", "Wondrous Item", "Common", 0, "A gold and jade amulet that draws domestic cats. You have Advantage on ability checks to find or call Tiny domestic cats and on Wisdom (Animal Handling) checks to deal with them.")
add("Celestial Circlet", "Wondrous Item", "Very Rare", 1, "A golden circlet with a halo that sheds Bright Light in 20 ft and Dim Light 20 ft more. You are always under Protection from Evil and Good, choosing a new creature type (not Celestials) each dawn. It has 7 charges and regains 1d4 + 3 at dawn. Spend charges to cast Cure Wounds (1 per spell level, up to level 4) or Spirit Guardians (3). Before or after, use a Bonus Action to fly up to 10 ft on angelic wings with no Opportunity Attacks. If you spend the last charge, roll a d20. On a 1 it loses its magic.", by="Cleric of Good alignment", ch=[7, "1d4 + 3", "dawn"])
SP["Celestial Circlet"] = {"sp": [["Cure Wounds", 1], ["Spirit Guardians", 3]]}
add("Ceratopper", "Wondrous Item", "Very Rare", 1, "An adamantine helm shaped like a triceratops. You gain +1 AC while wearing it. If you move at least 20 ft in a straight line then hit with an Unarmed Strike using it, the hit deals 3d4 plus your Strength modifier Piercing, and a target no more than one size larger makes a DC 13 Strength save or is Prone. You can also cast Polymorph from it to become a Triceratops, then not again for 2 days.", fx={"ac": 1})
SP["Ceratopper"] = {"sp": [["Polymorph", 1]]}
add("Charlatan's Wardrobe", "Wondrous Item", "Uncommon", 0, "Plain, comfortable, always clean and lightly perfumed clothes. Magic action: twirl and speak a command word to change their appearance as an illusion. A creature that takes a Study action can see through it with a DC 13 Intelligence (Investigation) check, and touching it reveals the illusion. They give no extra protection and can only look like clothes.")
add("Chillspike", "Weapon", "Legendary", 1, "A Pike with a never-melting ice spike. You gain +1 to attack and damage rolls and a hit deals an extra 1d10 Cold. It ignores Resistance to Cold. When you reduce a Large or smaller creature to 0 Hit Points, you can entomb it in ice for 1 minute (it cannot be Prone and makes no Death Saves, ice AC 12, HP 20, immune to Poison and Psychic, vulnerable to Fire, and it crumbles if healed or destroyed). **Everglacier's Fury.** Magic action: plunge it into the ground to raise icy spikes under up to three targets within 20 ft. Each makes a DC 16 Dexterity save or takes 2d8 Cold.", fx={"atk": 1, "dmg": 1}, base=["Pike"], xd=["Cold: +1d10"])
add("Chromacloth", "Weapon", "Uncommon", 0, "A silken cloth in red, yellow, green or blue, which you can change with a Magic action. The first time you take damage of the color's type while wearing it, you have Resistance to that damage, then not again until dawn. It can also be a Sling, whose ammunition deals the color's type instead of Bludgeoning. Red is Fire, yellow Lightning, green Poison and blue Cold.", base=["Sling"], ch=[1, "1", "dawn"])
add("Cinnabar Rapier", "Weapon", "Rare", 0, "A Rapier coated in toxic cinnabar. It has 10 charges and regains 1d8 + 2 at dawn. When you hit, spend 1 or more charges to deal an extra 1d4 Poison per charge.", base=["Rapier"], ch=[10, "1d8 + 2", "dawn"])
add("Circlet of the Huntsman's Third Eye", "Wondrous Item", "Very Rare", 1, "A barbed circlet with a preserved eye. You have Advantage on Wisdom (Survival) checks. It has 5 charges and regains all at dusk. Bonus Action, 1 charge: cast Hunter's Mark, with Advantage on Constitution saves to keep Concentration on it. Spend 1 charge as a Bonus Action (or 1 more when casting Hunter's Mark) for Truesight 120 ft for 1 minute. **Curse.** Attuning curses you until Remove Curse or similar magic, and while cursed you take 1d6 Psychic whenever you roll a 1 on an attack roll or ability check.", ch=[5, "all", "dusk"])
SP["Circlet of the Huntsman's Third Eye"] = {"sp": [["Hunter's Mark", 1]]}
add("Cloak of the Boundless Spirit", "Wondrous Item", "Rare", 1, "A translucent cloak that bolsters allies. It has 3 charges and regains all at dawn. Reaction, 1 charge: when an ally you can see within 15 ft takes damage, reduce it by 2d6. When an ally within 15 ft rolls 19 or 20 on a Death Saving Throw it regains 1 Hit Point, and you can spend a Reaction and 1 charge to give them 2d6 Temporary Hit Points. An ally can gain the 1 Hit Point from a 19 only once per Long Rest.", ch=[3, "all", "dawn"])
add("Clockwork Faefly", "Wondrous Item", "Uncommon", 0, "A 2-inch brass faefly. Bonus Action: tap it twice and it hovers 5 ft up, following you within 60 ft. It has AC 10, HP 10, Immunity to Poison and Psychic, and Resistance to other damage, and it is an object. While it flies, Bonus Action: move it 20 ft. If you are within 60 ft, Magic action: make it shine as Light or cast Faerie Fire (DC 13) in a 20-ft Cube from it, with no Concentration. Faerie Fire is usable once per dawn. Mending heals it 2d6, and at 0 Hit Points it is unusable for 2 days.", ch=[1, "1", "dawn"])
SP["Clockwork Faefly"] = {"sp": [["Faerie Fire", 1], ["Light", 0]], "dc": 13}
add("Clockwork Healerbee", "Wondrous Item", "Rare", 1, "A 2-inch brass and glass bee that hovers at your side. It has 8 charges and regains 1d6 + 2 at dawn. While it is in your space, Bonus Action with a command word and up to 3 charges: it heals a creature you can see within 20 ft for 1d6 Hit Points per charge, with a burst of Bright Light, then returns. It has AC 15, HP 10, Immunity to Poison and Psychic, and Resistance to other damage, and it is an object. Mending heals it 2d6, and at 0 Hit Points it is unusable for 24 hours.", ch=[8, "1d6 + 2", "dawn"])
add("Clockwork Inkbeetle", "Wondrous Item", "Uncommon", 0, "A 1-inch mechanical beetle. Set on parchment you carry and it draws a to-scale map of your journey in permanent ink, even inside a book, always knowing north. Magic action: turn its dial to choose 20 ft, 200 ft, 2 miles or 20 miles per inch. It is immune to effects that change its sense of direction and stamps a compass rose first. Attached to a Band of the Found and Lost while you wear the other, it tracks you from afar on the same plane.")
add("Coil Crook", "Staff", "Uncommon", 0, "A red staff of rigid silk rope that is a Spellcasting Focus. Bonus Action with a command word: it becomes a 10-ft Rope, and again to return. Either form is a Focus. You can cast Rope Trick from it, using it as the rope. Usable once per dawn.", base=["Quarterstaff"], ch=[1, "1", "dawn"])
SP["Coil Crook"] = {"sp": [["Rope Trick", 1]]}
add("Coldsnap", "Weapon", "Rare", 1, "A Whip with +1 to attack and damage rolls that deals an extra 1d4 Cold on a hit. It has 3 charges and regains all at dawn. When you hit a creature without Cold Immunity, spend 1 charge to force a DC 15 Constitution save. On a failure its Speed is 0 until the start of your next turn, and on a success its Speed is halved.", fx={"atk": 1, "dmg": 1}, base=["Whip"], xd=["Cold: +1d4"], ch=[3, "all", "dawn"])
add("Companion's Band", "Wondrous Item", "Common", 1, "A woven band. Magic action: summon a spectral Small or smaller Beast companion (dog, cat, bird or similar) within 5 ft. It sheds Dim Light in 5 ft, stays within 30 ft of you, is Friendly, and is a magical creation (not a creature) that cannot speak. After 7 days in a row of staying or being summoned, the band links to you: it no longer needs attunement, no one else can attune to it, you summon as a Bonus Action, and the companion can be touched.")
add("Container of Heat and Frost", "Wondrous Item", "Common", 0, "A 1-gallon iron container with three glyphs on its lid. Magic action: press one to boil the liquid (212 F), chill it (33 F), or hold its temperature between 33 and 212 F. Boiling or chilling takes 1 minute, pressing again stops it early, and the temperature then holds.")
add("Coralshield Golem", "Armor", "Uncommon", 1, "A crablike golem of light magical coral worn on your back. Bonus Action: it crawls down your arm and becomes a Shield, and another Bonus Action returns it to your back. If you have no free hand and will not drop what you hold, it reattaches to your back.", base=["Shield"])
add("Couatl Herald's Guard", "Armor", "Uncommon", 1, "A yew Shield covered in couatl feathers. Reaction: when a creature you can see within 10 ft takes damage, you take it instead and the damage becomes Force. Usable once per Short or Long Rest. **Flight of the Couatls.** While you are attuned to three items with this property, you gain a Fly Speed of 30 ft, or 30 ft more if you already have one.", base=["Shield"], by="Creature of Good alignment", ch=[1, "1", "short"])
add("Couatl Herald's Lash", "Weapon", "Rare", 1, "A feathered Whip with its weight cut and the Light property, plus +1 to attack and damage rolls. Once each turn when you take the Attack action, you can give up one attack to bind a Medium or smaller creature in reach. It makes a DC 15 Dexterity save or is Grappled and takes 1d4 Bludgeoning. A Grappled target failing again is Restrained. It can end this with an action and a DC 15 Strength (Athletics) or Dexterity (Acrobatics) check, or by moving over 10 ft away or by you dropping the Whip. **Flight of the Couatls.** Attuned to three such items, you gain a Fly Speed of 30 ft (or +30 ft).", fx={"atk": 1, "dmg": 1}, base=["Whip"], by="Creature of Good alignment")
add("Couatl Herald's Mantle", "Wondrous Item", "Uncommon", 1, "A cloak given to the kindhearted by a Celestial. You have Advantage on saves to avoid or end the Poisoned condition and magical contagions, and are immune to effects that sense your emotions. **Flight of the Couatls.** Attuned to three such items, you gain a Fly Speed of 30 ft (or +30 ft).", by="Creature of Good alignment")
add("Couatl Herald's Radiance", "Staff", "Rare", 1, "A wooden staff made by a couatl, with 5 charges that return 1d3 + 2 at dawn. Spend 1 charge to cast Create Food and Water, Cure Wounds (level 2), Lesser Restoration, Protection from Poison, Sanctuary or Shield with your spellcasting ability and save DC. If you spend the last charge, roll a d20. On a 1 it vanishes forever. **Flight of the Couatls.** Attuned to three such items, you gain a Fly Speed of 30 ft (or +30 ft).", base=["Quarterstaff"], by="Creature of Good alignment", ch=[5, "1d3 + 2", "dawn"])
SP["Couatl Herald's Radiance"] = {"sp": [["Create Food and Water", 1], ["Cure Wounds", 1, 2], ["Lesser Restoration", 1], ["Protection from Poison", 1], ["Sanctuary", 1], ["Shield", 1]]}
add("Couatl Herald's Scales", "Armor", "Rare", 1, "Scale Mail of couatl scales. It gives +1 AC and does not impose Disadvantage on Stealth checks. **Tooth and Scale.** Reaction when a creature within 10 ft damages you: a spectral couatl strikes it. It makes a DC 15 Dexterity save and takes 4d10 Radiant on a failure, or half on a success. Usable once per dawn. **Flight of the Couatls.** Attuned to three such items, you gain a Fly Speed of 30 ft (or +30 ft).", fx={"ac": 1}, base=["Scale Mail"], by="Creature of Good alignment", ch=[1, "1", "dawn"])
add("Cratering Quarterstaff", "Weapon", "Very Rare", 0, "A stony, ember-warm Quarterstaff that needs Strength 17 or higher to wield well. You gain +1 to attack and damage rolls. It has 5 charges and regains 1d4 + 1 at dawn. Once per turn right after an attack roll with it, spend 1 charge (no action) to slam it into the ground, making a 10-ft Cone of tremors and flame toward the target. Each creature in it makes a DC 16 Dexterity save (the target has Disadvantage) and takes 1d8 Bludgeoning and 1d8 Fire on a failure, or half on a success.", fx={"atk": 1, "dmg": 1}, base=["Quarterstaff"], ch=[5, "1d4 + 1", "dawn"])
add("Crosier of Divine Power", "Staff", "Very Rare", 1, "A staff wielded as a Quarterstaff with +3 to attack and damage rolls. When you roll Initiative against an enemy it makes 2 motes of holy power, and at the start of each combat turn roll a d6, and on a 6 a new mote appears. When you hit with it or heal with a spell or effect while holding it, spend 1 mote to add 2d6 to the damage (Radiant) or healing. A mote lasts 1 minute.", fx={"atk": 3, "dmg": 3}, base=["Quarterstaff"], by="Cleric or Paladin")
add("Crown of Deep Winter", "Wondrous Item", "Very Rare", 1, "An icy crown from the Everglacier that gives you Resistance to Cold damage. You can cast Fire Shield from it using the chill shield option, once per dawn. **Frozen Burst.** Reaction when a creature you can see within 5 ft hits you with an attack roll: icicles burst out. Other creatures within 5 ft make a DC 16 Dexterity save and take 2d8 Cold on a failure, or half on a success. Usable once per Short or Long Rest.", fx={"res": ["Cold"]}, ch=[1, "1", "dawn"])
SP["Crown of Deep Winter"] = {"sp": [["Fire Shield", 1]]}
add("Crypt Keeper Glaive", "Weapon", "Legendary", 1, "A Glaive with +3 to attack and damage rolls. When you reduce a Small or larger Hostile creature to 0 Hit Points with it, you gain 1d10 Temporary Hit Points and the blade glows green. Your next melee hit with it deals extra Necrotic damage equal to those Temporary Hit Points. The haze and leftover Temporary Hit Points vanish after 1 minute. Undead it kills cannot be raised again. **Six Feet Under.** The first time each turn you hit a Prone target with it, it deals maximum damage.", fx={"atk": 3, "dmg": 3}, base=["Glaive"])
add("Dagger of the Ogre Mage", "Weapon", "Uncommon", 1, "An ogre's dagger that is large enough to be a Shortsword. You gain +1 to attack and damage rolls. Its hollow hilt holds up to three Spell Scrolls. A cantrip scroll left inside for 1 minute lights one of three gems, and you can then cast that cantrip at will with your spell save DC and attack modifier, using the sword as a Spellcasting Focus that can also supply Somatic components. The scrolls do not crumble. When a damage cantrip is cast this way, the sword's damage type becomes the cantrip's for 1 minute or until you end it.", fx={"atk": 1, "dmg": 1}, base=["Shortsword"])
add("Couatl Herald's Fang", "Weapon", "Rare", 1, "Any sword or dagger, forged by or from the scales of a couatl. You gain +1 to attack and damage rolls. When you roll a 20 to hit, the target takes an extra 2d6 Poison and makes a DC 15 Constitution save. On a failure it is Incapacitated with Speed 0 until it takes damage or another creature uses an action to shake it out of the stupor. **Flight of the Couatls.** Attuned to three such items, you gain a Fly Speed of 30 ft (or +30 ft).", fx={"atk": 1, "dmg": 1}, by="Creature of Good alignment")
add("Couatl Herald's Reach", "Weapon", "Rare", 1, "Any bow carved like a couatl. You gain +1 to attack and damage rolls. It has 4 charges and regains 1d3 + 1 at dawn. When you make a ranged attack against a Large or smaller creature, pick a limb and spend 1 charge. A hit deals Radiant damage instead, and the target makes a DC 15 Dexterity save or the limb is pinned for up to 1 minute. The GM decides whether it falls Prone, cannot move or attacks with Disadvantage. The target or a creature within 5 ft can free it with an action and a DC 15 Strength (Athletics) check. **Flight of the Couatls.** Attuned to three such items, you gain a Fly Speed of 30 ft (or +30 ft).", fx={"atk": 1, "dmg": 1}, by="Creature of Good alignment", ch=[4, "1d3 + 1", "dawn"])
add("Dark Fathom Armor", "Armor", "Very Rare", 1, "Sea-soaked Studded Leather covered in eldritch runes. You gain +1 AC and can breathe underwater. You can cast Evard's Black Tentacles (save DC 15) from it, centered on you as a 15-ft square that does not follow you. It needs no Concentration and you are immune to it. Usable once per dusk.", fx={"ac": 1}, base=["Studded Leather Armor"], ch=[1, "1", "dusk"])
SP["Dark Fathom Armor"] = {"sp": [["Evard's Black Tentacles", 1]], "dc": 15}
add("Dead Ringer", "Wondrous Item", "Rare", 0, "A bronze mask that rings when struck. When you drop to 0 Hit Points or fail a Death Saving Throw while wearing it, the three enemies nearest you within 30 ft make a DC 15 Wisdom save or take 2d12 Necrotic. A target at full Hit Points or Deafened automatically succeeds. If you are healed or stabilized after dropping to 0, it cannot be used again until the next dusk.")
add("Death Knell", "Weapon", "Rare", 1, "A grimly ornate Halberd with +2 to attack and damage rolls. Once per turn when you reduce a Small or larger creature to 0 Hit Points with it, a gonglike sound rings out. Each enemy within 15 ft of the target that is missing any Hit Points makes a DC 15 Wisdom save and takes 1d8 Psychic on a failure, or half on a success.", fx={"atk": 2, "dmg": 2}, base=["Halberd"])
add("Devil's Detail Eyepatch", "Wondrous Item", "Uncommon", 0, "A leather eyepatch with an illusory embroidered eye that moves as you look around. Worn over an eye, whether you lack one or not, you see through the patch as through a working eye. Bonus Action with a command word: gain Darkvision 60 ft for 1 hour (60 ft more if you already have it) and see through magical Darkness as if nonmagical. Usable once per dawn.", ch=[1, "1", "dawn"])
add("Direstone Dwarven Pick", "Weapon", "Rare", 1, "A weathered War Pick that breaks and molds stone. You gain +2 to attack and damage rolls, and stone creatures and objects it hits take an extra 1d8 Piercing. It has 3 charges and regains 1d3 at dawn. Spend 1 charge to cast Meld into Stone or Stone Shape.", fx={"atk": 2, "dmg": 2}, base=["War Pick"], by="Dwarf", ch=[3, "1d3", "dawn"])
SP["Direstone Dwarven Pick"] = {"sp": [["Meld into Stone", 1], ["Stone Shape", 1]]}
add("Discordant Thunderstave", "Weapon", "Uncommon", 1, "A hollow Quarterstaff with +1 to attack and damage rolls that also has the Finesse property. When you hit and roll the maximum on the weapon's damage die, roll that die again and add it as Thunder damage.", fx={"atk": 1, "dmg": 1}, base=["Quarterstaff"])
add("Doodle Ring", "Ring", "Common", 0, "A wooden ring always smeared with charcoal, ink or paint. Touch the finger to a solid surface and draw as with charcoal, an ink quill or a brush (your choice), in any color. Marks smudge or wash off without a trace and fade after 24 hours. It can hold 5 square feet of drawing, and drawing more erases the earliest marks.")
add("Doomsday Cookie", "Wondrous Item", "Uncommon", 0, "A black sugarpaste cookie with a blank paper strip inside. Breaking it open shows a vague prediction of how you will die. Roll 1d20 on its table (for example, 1 is fiery passions, 9 is a fine meal, 20 is rocks falling). Once your death is predicted, every later cookie shows the same result for you. If you die in the foretold manner (GM's call), the paper becomes a Spell Scroll of Revivify usable only on you, and it crumbles into flour after 1 minute. The cookie is also a sweet, salty, smoky snack.")
add("Dragon Edge Weapon", "Weapon", "Uncommon", 0, "A simple Piercing or Slashing weapon forged from a fallen dragon's claw or tooth, giving +1 to attack and damage rolls. The first time each turn you hit with an attack roll you had Advantage on, it deals an extra 1d6 damage of the type of the dragon's breath weapon. Young dragons give Uncommon weapons, adults Rare and ancient Very Rare, with a bonus set by rarity.", fx={"atk": 1, "dmg": 1}, xd=["Hit with Advantage: +1d6 (dragon breath type)"])
add("+1 Dragon Edge Weapon", "Weapon", "Rare", 0, "A simple Piercing or Slashing weapon forged from a fallen dragon's claw or tooth, giving +1 to attack and damage rolls. The first time each turn you hit with an attack roll you had Advantage on, it deals an extra 1d6 damage of the type of the dragon's breath weapon. Young dragons give Uncommon weapons, adults Rare and ancient Very Rare, with a bonus set by rarity.", fx={"atk": 1, "dmg": 1}, xd=["Hit with Advantage: +1d6 (dragon breath type)"])
add("+2 Dragon Edge Weapon", "Weapon", "Very Rare", 0, "A simple Piercing or Slashing weapon forged from a fallen dragon's claw or tooth, giving +2 to attack and damage rolls. The first time each turn you hit with an attack roll you had Advantage on, it deals an extra 1d6 damage of the type of the dragon's breath weapon. Young dragons give Uncommon weapons, adults Rare and ancient Very Rare, with a bonus set by rarity.", fx={"atk": 2, "dmg": 2}, xd=["Hit with Advantage: +1d6 (dragon breath type)"])
_dk = "A Melee weapon of scaly metal that radiates draconic elements. A hit deals an extra 1d6 damage of the type of your Dragonborn Breath Weapon, and while attuned your Breath Weapon save DC rises by the same bonus. Its metal takes on your natural colors once you attune."
add("+1 Dragonkin Weapon", "Weapon", "Rare", 1, _dk + " You gain +1 to attack and damage rolls.", fx={"atk": 1, "dmg": 1}, xd=["Breath Weapon type: +1d6"], by="Dragonborn")
add("+2 Dragonkin Weapon", "Weapon", "Very Rare", 1, _dk + " You gain +2 to attack and damage rolls.", fx={"atk": 2, "dmg": 2}, xd=["Breath Weapon type: +1d6"], by="Dragonborn")
add("+3 Dragonkin Weapon", "Weapon", "Legendary", 1, _dk + " You gain +3 to attack and damage rolls.", fx={"atk": 3, "dmg": 3}, xd=["Breath Weapon type: +1d6"], by="Dragonborn")
add("Acidlight Ammunition", "Weapon", "Rare", 0, "Any ammunition coated in an alchemical mix that ignites on impact, shedding Bright Light in the target's space and Dim Light in a 5-ft Emanation for 1 minute. A creature hit takes 1d4 Acid at the start of each of its turns and has Disadvantage on Dexterity (Stealth) checks while it stays lit. The piece stays lodged until a creature uses a Utilize action to remove and snuff it, the target cannot benefit from Invisible while it is lodged, and the piece is destroyed.")
add("Battlement Bow", "Weapon", "Uncommon", 1, "Any bow with passive Abjuration wards. When you hit a creature with a ranged attack, a thin barrier of magic stays between you and it until the start of your next turn. Hitting a different creature moves the barrier to the new target. Against the creature the barrier guards you from, you have Half Cover against its ranged attacks and effects that originate from it.")
add("Dragon Tamer Lance", "Weapon", "Legendary", 1, "An iridescent Lance with +1 to attack and damage rolls that teaches you Draconic while attuned. It has 8 charges and regains 1d4 + 4 at dawn. When you hit, spend 1 charge for an extra 3d6 Acid, Cold, Fire, Lightning or Poison. A Dragon hit this way also makes a DC 17 Wisdom save or is Frightened until the start of your next turn. After spending a charge you can spend a second for 1d6 more of the same type, and the target cannot take Reactions until the start of its next turn. **Wyrmling Steed.** Cast Find Steed from it once per dawn, optionally summoning a dragon wyrmling (no breath weapon, counts as one size larger when ridden) for charges equal to its CR (max 2), with matching alignment. **Forceful Impact.** Moving 20 ft in a line toward a Medium or smaller target within 5 ft gives Advantage on the melee attack, and a hit allows an extra attack against a different target directly behind it within 5 ft and not behind Cover.", fx={"atk": 1, "dmg": 1}, base=["Lance"], ch=[8, "1d4 + 4", "dawn"])
SP["Dragon Tamer Lance"] = {"sp": [["Find Steed", 1]]}
add("Dragon Turtle Shield", "Armor", "Rare", 0, "A Shield of dragon turtle shell with a brass turtle head that makes and heats a small reservoir of water each dawn. Reaction when you take Fire damage while holding it: say a command word to superheat the water and halve that damage. The water bursts into a stationary cloud of steam, a 45-ft-diameter Emanation around you that is Heavily Obscured for 1 minute (or until a strong wind disperses it). The reservoir then stays empty until dawn, or until the Shield spends 1 hour in nonmagical salt water.", base=["Shield"], ch=[1, "1", "dawn"])
